
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_vsxc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_vsxc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.371230734058361e-02, -4.434701541697564e-02, -4.525652510701628e-02, -4.655114351107682e-02, -4.836348544246022e-02, -5.079249016525792e-02, -5.365550531547805e-02, -5.558230777639282e-02, -5.165955058077860e-02, -3.541376944091044e-02, -3.712229252739219e-02, -1.327537118397913e-01, -2.674714791217598e-02, -2.836916611994785e-02, -1.557605921615453e-02, -1.013704405090605e-03, -3.235269288332501e-03, -3.378725786450460e-04, -3.487502451765039e-06, -3.611779902595943e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


